<?php
namespace App\Controllers\Admin;use App\Core\Controller;use App\Helpers\AdminAuth;
class Customers extends Controller {
 public function index():void{$this->handleCors();$this->admin();$rows=$this->db()->query('SELECT c.id,c.email,c.full_name,c.phone,c.status,c.last_login_at,c.created_at,(SELECT COUNT(*) FROM vp_orders o WHERE o.customer_id=c.id) order_count,(SELECT COUNT(*) FROM vp_customer_addresses a WHERE a.customer_id=c.id) address_count FROM vp_customers c ORDER BY c.created_at DESC LIMIT 500')->result_array()?:[];foreach($rows as &$r){$r['id']=(int)$r['id'];$r['order_count']=(int)$r['order_count'];$r['address_count']=(int)$r['address_count'];}unset($r);$this->success(['items'=>$rows],'Customers loaded');}
 public function show($id=null):void{$this->handleCors();$this->admin();$id=(int)$id;$c=$this->db()->query('SELECT id,email,full_name,phone,status,avatar_url,last_login_at,created_at FROM vp_customers WHERE id=? LIMIT 1',[$id])->row_array();if(!$c)$this->error('Pelanggan tidak ditemukan',404);$c['id']=(int)$c['id'];$addr=$this->db()->query('SELECT id,label,recipient_name,recipient_phone,address_line,area_name,postal_code,province_name,regency_name,district_name,village_name,is_default FROM vp_customer_addresses WHERE customer_id=? ORDER BY is_default DESC,updated_at DESC',[$id])->result_array()?:[];foreach($addr as &$a){$a['id']=(int)$a['id'];$a['is_default']=(int)$a['is_default'];}unset($a);$c['addresses']=$addr;$orders=$this->db()->query('SELECT o.id,o.order_number,o.status,o.total,o.created_at,p.status payment_status FROM vp_orders o LEFT JOIN vp_payments p ON p.order_id=o.id WHERE o.customer_id=? ORDER BY o.created_at DESC LIMIT 50',[$id])->result_array()?:[];foreach($orders as &$o){$o['id']=(int)$o['id'];$o['total']=(float)$o['total'];}unset($o);$c['orders']=$orders;$this->success($c,'Customer loaded');}
 public function update_status($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$id=(int)$id;$status=(string)($this->getBody()['status']??'');if(!in_array($status,['active','blocked'],true))$this->error('Status tidak valid',422);if(!$this->db()->query('SELECT id FROM vp_customers WHERE id=? LIMIT 1',[$id])->row_array())$this->error('Pelanggan tidak ditemukan',404);$this->db()->update('vp_customers',['status'=>$status,'updated_at'=>$GLOBALS['now']??date('Y-m-d H:i:s')],['id'=>$id]);$this->success(null,'Status pelanggan diperbarui');}
 private function admin():array{$a=AdminAuth::user();if(!$a)$this->error('Unauthorized',401);return $a;}
}
